// <diletta-toast> — a INSTÂNCIA WEB de `design-system-toast`.
//
// A ÚLTIMA peça a atravessar, e ela ficou de fora por um diagnóstico errado meu, não
// por dificuldade. A tabela de resolução dizia "cor composta com alfa não é papel
// nenhum" e mandava os quatro fundos para `coresSemPapel`; o gerador, corretamente,
// recusava a peça inteira por causa deles.
//
// O fundo é <papel>Subtle a 70,2% — os DOIS lados declarados no Dart. Achatar os dois
// num hex é que perdia a procedência. Corrigida a medição, a peça saiu limpa sem
// nenhuma decisão de desenho nova.
import { papeisDe, tinta, eixo } from './base.js';
import './diletta-spot-icon.js';

const SLUG = 'design-system-toast';
const STATE = ['normal', 'success', 'error', 'warning'];

// O glifo é do ESTADO, e é regra da spec — não escolha de quem chama. São os mesmos
// quatro que o Dart passa pro spot (hand-wave · check · xmark · triangle-exclamation),
// redesenhados em 16 porque a web não embarca o pacote de ícones do pai.
const GLIFO = {
  normal:
    '<path d="M5.5 9.6V4.3a1.1 1.1 0 0 1 2.2 0v3m0-.4V3.2a1.1 1.1 0 0 1 2.2 0v4m0-.4a1.1 1.1 0 0 1 2.2 0v2.9m0-1.3a1.1 1.1 0 0 1 2.1 0v2.4c0 2.6-1.9 4.6-4.5 4.6-2 0-3.2-.9-4-2.4L3.7 10a1.1 1.1 0 0 1 1.8-1z"/>',
  success: '<path d="M4 8.6l3 3L12.4 5"/>',
  error: '<path d="M5 5l6.5 6.5M11.5 5L5 11.5"/>',
  warning:
    '<path d="M8 2.8L14.5 13.6h-13z" stroke-linejoin="round"/><path d="M8 6.6v3.2M8 11.9v.1"/>',
};

class DilettaToast extends HTMLElement {
  static observedAttributes = ['state', 'titulo', 'subtitulo'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  render() {
    const state = eixo(this, 'state', STATE, 'normal');
    const p = papeisDe(SLUG, { State: state });
    const titulo = this.getAttribute('titulo') || '';
    const subtitulo = this.getAttribute('subtitulo');

    // role=status com aria-live=polite é o que o `liveRegion: true` do Dart vira aqui.
    // `assertive` interromperia a leitura em curso, e o toast é confirmação: quem
    // precisa de interrupção é erro de campo, que não é esta peça.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-flex; max-width: 420px; }
        /* O VIDRO: o desfoque vem do token, e o token vem da paleta do filho. Sigma
           escrito à mão aqui é a mesma dívida que o gate do lado Dart pega, e ele
           agora varre esta pasta também. */
        .toast {
          box-sizing: border-box; width: 100%;
          display: flex; align-items: center; gap: 8px;
          padding: var(--cps-s2, 8px) var(--cps-s3, 12px);
          /* LONGHAND, sempre. A abreviacao de borda reescreve os tres subvalores,
             e uma cor pintada antes dela some sem erro nenhum — o pacote proibe a
             abreviacao por gate justamente por isso. (Sem crase: template literal.) */
          border-width: 1px; border-style: solid; border-color: ${tinta(p.border)};
          border-radius: var(--cps-r8, 8px);
          background: ${tinta(p.bg)};
          backdrop-filter: blur(var(--cps-glassBlur, 10px));
          -webkit-backdrop-filter: blur(var(--cps-glassBlur, 10px));
          /* SEM valor de reserva, e por regra do pacote: reserva de sombra e um hex
             cru escrito dentro da peca. Se a folha de token nao carregou, a peca
             fica sem sombra — nunca com uma sombra que ninguem declarou. */
          box-shadow: var(--cps-elevation-soft);
        }
        .texto { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
        /* subheading 14/600 — o mesmo papel de tipo que o Dart aplica no título. */
        .titulo {
          color: ${tinta(p.color)};
          font-size: var(--cps-type-subheading-size, 14px);
          font-weight: var(--cps-type-subheading-weight, 600);
          line-height: var(--cps-type-subheading-line-height, 20px);
        }
        /* O subtítulo tem SLOT PRÓPRIO de tinta (colorSubtitulo), e é por isso que ele
           não sai de estiloDa: aquele helper pinta o hospedeiro, e este texto é um
           pedaço de dentro. Os dois são neutros em degraus diferentes; somá-los num
           color só esconderia qual é qual. */
        .sub { color: ${tinta(p.colorSubtitulo)}; font-size: 13px; line-height: 16px; }
      </style>
      <div class="toast" part="toast" role="status" aria-live="polite">
        <diletta-spot-icon state="${state}" part="spot">
          <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none"
               stroke="currentColor" stroke-width="1.5" stroke-linecap="round">
            ${GLIFO[state]}
          </svg>
        </diletta-spot-icon>
        <span class="texto">
          <span class="titulo" part="titulo">${titulo}</span>
          ${subtitulo ? `<span class="sub" part="subtitulo">${subtitulo}</span>` : ''}
        </span>
      </div>`;
  }
}

customElements.define('diletta-toast', DilettaToast);
export { DilettaToast };
